cat > classic/apps/electron/test/agent-computer.test.js <<'EOF'
const {test}=require("node:test");
const assert=require("node:assert/strict");
const fs=require("node:fs/promises");
const os=require("node:os");
const path=require("node:path");
const {createComputerService}=require("../app/agent-computer.cjs");
const scope={accountId:"alice",projectId:"film",generation:1,mode:"askDestructive"};
async function fixture(t,options={}) {
 const dir=await fs.mkdtemp(path.join(os.tmpdir(),"opencut-computer-"));t.after(()=>fs.rm(dir,{recursive:true,force:true}));
 const prompts=[];let allowed=true,valid=true;
 const service=createComputerService({confirm:async info=>{prompts.push(info);return allowed;},assertScope:async()=>{if(!valid)throw Error("Scope changed");},...options});
 t.after(()=>service.revoke());
 const execute=(operation,id="op-1",extra={})=>service.execute({...scope,operationId:id,operation,...extra});
 return {dir,service,prompts,execute,deny:()=>{allowed=false;},invalidate:()=>{valid=false;}};
}
test("computer is disabled by default, grants are scoped and revocation fences IO",async t=>{
 const f=await fixture(t);
 await assert.rejects(f.execute({type:"list",path:f.dir}),/off/);
 await f.service.setAccess({...scope,enabled:true});
 await assert.rejects(f.execute({type:"list",path:f.dir},"other",{projectId:"other"}),/off/);
 f.service.revoke();await assert.rejects(f.execute({type:"list",path:f.dir}),/off/);
});
test("inspection and optimistic writes ask exact native approval; replay is idempotent",async t=>{
 const f=await fixture(t);await f.service.setAccess({...scope,enabled:true});
 const file=path.join(f.dir,"notes.txt"),op={type:"write",path:file,content:"hello",expectedSha256:null};
 const result=await f.execute(op);
 assert.equal(await fs.readFile(file,"utf8"),"hello");assert.equal(f.prompts.length,2);assert.match(f.prompts[1].detail,/hello/);
 assert.deepEqual(await f.execute(op),result);assert.equal(f.prompts.length,2);
 await assert.rejects(f.execute

